css:
html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;
  background: transparent !important;
}

.text-widget,
.text-widget * {
  box-sizing: border-box;
}

.text-widget {
  display: flex;
  align-items: center;
  justify-content: center;

  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;

  border: none;
  background: transparent;
  pointer-events: none;
  user-select: none;

  opacity: var(--w-opacity, 1);
}

.text-content {
  display: block;
  flex: 0 0 auto;

  width: max-content;
  margin: 0;
  padding: 0;

  color: var(--w-color, #246875);

  font-family:
    "Bahnschrift",
    "Segoe UI",
    Arial,
    sans-serif;

  font-size: var(--w-font-size, 20px);
  font-weight: var(--w-bold, normal);
  font-style: normal;

  /*
   * Misma proporción que el título anterior:
   * 18 px de interlineado para una fuente de 16 px.
   */
  line-height: 1.125;

  letter-spacing: 0;
  word-spacing: normal;
  text-align: center;

  /* Conserva los saltos generados mediante "//". */
  white-space: pre;

  transform: scale(var(--text-scale, 1));
  transform-origin: center center;
}

js:
"use strict";

(function () {
  const BASE_WIDTH = 200;
  const BASE_HEIGHT = 40;
  const DEFAULT_TEXT = "Texto";

  let container = null;
  let textElement = null;
  let lastUpdate = null;
  let pendingFrame = null;
  let resizeObserver = null;

  function parseName(name) {
    if (typeof name !== "string" || name.trim() === "") {
      return DEFAULT_TEXT;
    }

    /*
     * Cada "//" genera una nueva línea.
     * También admite saltos de línea reales.
     */
    const text = name
      .split(/\/\/|\r\n|\n|\r/)
      .map(function (line) {
        return line.replace(/\s+/g, " ").trim();
      })
      .join("\n")
      .trim();

    return text || DEFAULT_TEXT;
  }

  function normalizeAlignment(value) {
    const alignment = String(value || "")
      .trim()
      .toLowerCase();

    if (
      alignment === "left" ||
      alignment === "start" ||
      alignment === "izquierda"
    ) {
      return "left";
    }

    if (
      alignment === "right" ||
      alignment === "end" ||
      alignment === "derecha"
    ) {
      return "right";
    }

    return "center";
  }

  function applyAlignment(widget) {
    const rootStyles = getComputedStyle(
      document.documentElement
    );

    const alignment = normalizeAlignment(
      widget.align ||
      widget.textAlign ||
      (widget.style && widget.style.align) ||
      rootStyles.getPropertyValue("--w-text-align").trim() ||
      rootStyles.getPropertyValue("--w-align").trim() ||
      "center"
    );

    // Alineación de las líneas dentro del bloque.
    textElement.style.textAlign = alignment;

    // Posición del bloque dentro del widget.
    if (alignment === "left") {
      container.style.justifyContent = "flex-start";
      textElement.style.transformOrigin = "left center";
    } else if (alignment === "right") {
      container.style.justifyContent = "flex-end";
      textElement.style.transformOrigin = "right center";
    } else {
      container.style.justifyContent = "center";
      textElement.style.transformOrigin = "center center";
    }
  }

  function fitText() {
    if (!container || !textElement) return;

    const width = container.clientWidth;
    const height = container.clientHeight;

    if (width <= 0 || height <= 0) return;

    /*
     * Medidas del bloque completo, incluyendo todas
     * las líneas, sin la transformación visual.
     */
    const textWidth = Math.max(
      1,
      textElement.offsetWidth,
      textElement.scrollWidth
    );

    const textHeight = Math.max(
      1,
      textElement.offsetHeight,
      textElement.scrollHeight
    );

    /*
     * Escalado proporcional al tamaño del widget.
     * Reduce el bloque adicionalmente si no cabe.
     */
    const scale = Math.min(
      width / BASE_WIDTH,
      height / BASE_HEIGHT,
      width / textWidth,
      height / textHeight
    );

    container.style.setProperty(
      "--text-scale",
      String(scale)
    );
  }

  function scheduleLayout() {
    if (pendingFrame !== null) return;

    pendingFrame = requestAnimationFrame(function () {
      pendingFrame = null;
      fitText();
    });
  }

  function render(w) {
    if (!container || !textElement) return;

    const widget = w || {};

    // El contenido procede exclusivamente de NOMBRE.
    textElement.textContent = parseName(widget.name);

    /*
     * Sin propiedades explícitas se utilizan
     * las variables CSS enviadas por el software.
     */
    textElement.style.removeProperty("color");
    textElement.style.removeProperty("font-size");
    textElement.style.removeProperty("font-weight");

    if (
      typeof widget.color === "string" &&
      widget.color.trim() !== ""
    ) {
      textElement.style.color = widget.color;
    }

    const fontSize = parseFloat(widget.fontSize);

    if (Number.isFinite(fontSize) && fontSize > 0) {
      textElement.style.fontSize = fontSize + "px";
    }

    if (typeof widget.bold === "boolean") {
      textElement.style.fontWeight =
        widget.bold ? "700" : "400";
    }

    applyAlignment(widget);
    scheduleLayout();
  }

  window.onWidgetUpdate = function (w) {
    lastUpdate = w;
    render(w);
  };

  function initialize() {
    container = document.querySelector(".text-widget");
    textElement = document.querySelector(".text-content");

    if (!container || !textElement) return;

    render(lastUpdate || window.WIDGET || null);

    if (document.fonts && document.fonts.ready) {
      document.fonts.ready.then(scheduleLayout);
    }

    if (typeof ResizeObserver !== "undefined") {
      resizeObserver = new ResizeObserver(scheduleLayout);
      resizeObserver.observe(container);
      resizeObserver.observe(textElement);
    } else {
      window.addEventListener("resize", scheduleLayout);
    }
  }

  if (document.readyState === "loading") {
    document.addEventListener(
      "DOMContentLoaded",
      initialize,
      { once: true }
    );
  } else {
    initialize();
  }
})();
